/**
 * Build identity module.
 *
 * Reads `app/build-identity.json` at runtime so the health endpoint can report
 * productVersion, gitSha, and uiFingerprint without depending on a Git checkout
 * at serve time.
 *
 * The file is generated by `scripts/write-build-identity.mjs` during `npm run build`.
 * If it is missing (e.g. running from source without a build), all fields fall
 * back to "unknown" rather than fabricating values.
 */

import { readdirSync, readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { join } from "node:path";

let cachedIdentity = null;

/**
 * Returns the build identity. Caches after the first read.
 *
 * @param {string} appDir - Absolute path to the app/ directory containing build-identity.json
 * @returns {{productVersion: string, gitSha: string, uiFingerprint: string, runtimeFingerprint: string}}
 */
export function getBuildIdentity(appDir) {
  if (cachedIdentity) return cachedIdentity;
  const fallback = { productVersion: "unknown", gitSha: "unknown", uiFingerprint: "unknown", runtimeFingerprint: "unknown" };
  try {
    const filePath = join(appDir, "build-identity.json");
    const raw = readFileSync(filePath, "utf-8");
    const parsed = JSON.parse(raw);
    cachedIdentity = {
      productVersion: typeof parsed.productVersion === "string" ? parsed.productVersion : "unknown",
      gitSha: typeof parsed.gitSha === "string" ? parsed.gitSha : "unknown",
      uiFingerprint: typeof parsed.uiFingerprint === "string" ? parsed.uiFingerprint : "unknown",
      runtimeFingerprint: typeof parsed.runtimeFingerprint === "string" ? parsed.runtimeFingerprint : "unknown",
    };
  } catch {
    cachedIdentity = fallback;
  }
  return cachedIdentity;
}

/**
 * Clears the cache. Used by tests that swap appDir.
 */
export function resetBuildIdentityCache() {
  cachedIdentity = null;
}

/**
 * Computes the UI fingerprint from every browser-delivered app shell file.
 * Keeping all local ES modules in the digest prevents a release identity from
 * claiming that the UI is unchanged when an imported implementation changed.
 *
 * @param {string} appDir - Absolute path to the app/ directory
 * @returns {string} SHA-256 hex digest, or "unknown" if files are unreadable
 */
export function computeUiFingerprint(appDir) {
  try {
    const hash = createHash("sha256");
    const names = readdirSync(appDir, { withFileTypes: true })
      .filter((entry) => entry.isFile() && (entry.name === "index.html" || entry.name === "styles.css" || entry.name.endsWith(".mjs")))
      .map((entry) => entry.name)
      .sort();
    if (!names.includes("index.html") || !names.includes("styles.css") || !names.includes("app.mjs")) return "unknown";
    for (const name of names) {
      hash.update(`${name}\0`);
      const content = readFileSync(join(appDir, name));
      hash.update(content);
    }
    return hash.digest("hex");
  } catch {
    return "unknown";
  }
}

/**
 * Computes an identity for the code that backs the local HTTP runtime. Unlike
 * gitSha this changes for uncommitted development edits, so a desktop shell
 * cannot silently attach to an older long-lived service from the same commit.
 *
 * @param {string} rootDir - Repository/app root containing server.mjs and lib/.
 * @returns {string} SHA-256 hex digest, or "unknown" if files are unreadable.
 */
export function computeRuntimeFingerprint(rootDir) {
  try {
    const hash = createHash("sha256");
    const files = [join(rootDir, "server.mjs"), ...runtimeFiles(join(rootDir, "lib"))]
      .sort((left, right) => left.localeCompare(right));
    for (const filePath of files) {
      const relativeName = filePath.slice(rootDir.length + 1).replaceAll("\\", "/");
      hash.update(`${relativeName}\0`);
      hash.update(readFileSync(filePath));
    }
    return hash.digest("hex");
  } catch {
    return "unknown";
  }
}

function runtimeFiles(directory) {
  const files = [];
  for (const entry of readdirSync(directory, { withFileTypes: true })) {
    const filePath = join(directory, entry.name);
    if (entry.isDirectory()) files.push(...runtimeFiles(filePath));
    else if (entry.isFile() && (entry.name.endsWith(".mjs") || entry.name.endsWith(".js") || entry.name.endsWith(".cjs"))) files.push(filePath);
  }
  return files;
}
